package cn.xi.cloudwidget;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import android.widget.*;
import java.io.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.*;

/** SAF documents only. ZIP work and copying stay off the main thread. */
public class BackupActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private TextView status;private boolean busy;private File generated;private Backup.Plan plan;private AlertDialog confirmation;
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=Ui.column(this);root.setPadding(Ui.dp(this,24),Ui.dp(this,24),Ui.dp(this,24),Ui.dp(this,24));Ui.root(this,root);root.addView(Controls.action(this,"‹ 返回",this::onBackPressed));root.addView(Controls.heading(this,"完整本地备份"));root.addView(Controls.hint(this,"保存卡片、照片、素材和打卡历史。备份不含桌面绑定，换手机后需要重新添加组件。"));status=Ui.text(this,"请选择导出备份或导入 ZIP。",14);root.addView(status);root.addView(Controls.primary(this,"导出完整备份",this::beginExport));Ui.gap(this,root,16);root.addView(Controls.action(this,"导入备份 ZIP",this::beginImport));String error=getSharedPreferences("backup-health",0).getString("error","");if(!error.isEmpty())status.setText("上次恢复检查需要处理："+error);if(state==null){if("export".equals(getIntent().getStringExtra("mode")))beginExport();if("import".equals(getIntent().getStringExtra("mode")))beginImport();}}
    private void ui(Runnable action){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())action.run();});}
    private void fail(String message,Throwable error){ui(()->{busy=false;status.setText(message+"\n"+(error.getMessage()==null?"请检查可用空间和文件提供器":error.getMessage()));});}
    void beginExport(){if(busy)return;busy=true;status.setText("正在生成并完整校验备份…");worker.execute(()->{try{Backup.recover(this);File archive=Backup.export(this);generated=archive;if(isFinishing()||isDestroyed()){Backup.remove(archive.getParentFile());return;}ui(()->{busy=false;Intent create=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"云朵小卡-"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss"))+"-"+java.util.UUID.randomUUID().toString().substring(0,6)+".zip");try{startActivityForResult(create,40);}catch(ActivityNotFoundException error){discardExport();status.setText("没有可用的系统文件选择器");}});}catch(Exception|OutOfMemoryError error){fail("备份未导出，原数据保留。",error);}});}
    void beginImport(){if(busy)return;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/zip","application/x-zip-compressed","application/octet-stream"}),41);}catch(ActivityNotFoundException error){status.setText("没有可用的系统文件选择器");}}
    private void discardExport(){if(generated!=null){Backup.remove(generated.getParentFile());generated=null;}}
    void cancelImport(){if(plan!=null){plan.close();plan=null;}status.setText("已取消，现有卡片及绑定没有改变。");}
    void confirmImport(){if(plan==null||busy)return;Backup.Plan selected=plan;plan=null;busy=true;status.setText("正在合并恢复，请稍等…");worker.execute(()->{try{int count=Backup.apply(this,selected,Backup.NONE);WidgetProvider.all(this);ui(()->{busy=false;status.setText(count==0?"此备份已恢复，未重复添加卡片。":"恢复完成，新增 "+count+" 张卡片。现有卡片及绑定保持原样。\n请到「组件」选择恢复的卡片，重新添加到桌面。");});}catch(Exception|OutOfMemoryError error){fail("恢复没有完成；原卡未覆盖。下次启动也会检查未完成事务。",error);}finally{selected.close();}});}
    @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=40&&request!=41)return;if(result!=RESULT_OK||data==null||data.getData()==null){if(request==40)discardExport();status.setText("已取消，原数据保留。");return;}Uri uri=data.getData();if(request==40){File archive=generated;if(archive==null){worker.execute(()->{try{DocumentsContract.deleteDocument(getContentResolver(),uri);}catch(Exception ignored){}});status.setText("临时备份已失效，请重新导出并检查刚选的空文档。");return;}if((data.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0)try{if((data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);if((data.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(SecurityException ignored){}busy=true;status.setText("正在写入所选位置并校验…");worker.execute(()->{try{Backup.exportDocument(this,archive,uri,Backup.NONE);ui(()->{busy=false;status.setText("备份保存成功，已核对完整文件哈希。\n保存位置："+uri);});}catch(Exception error){boolean removed=false;try{removed=DocumentsContract.deleteDocument(getContentResolver(),uri);}catch(Exception ignored){}final boolean cleaned=removed;fail("未成功导出。"+(cleaned?"本次不完整文档已清理。":"请在刚选的位置检查并移除本次不完整文件。"),error);}finally{discardExport();}});}else{busy=true;status.setText("正在校验文件、资源、哈希和完整引用，尚未恢复数据…");worker.execute(()->{try{Backup.recover(this);Backup.Plan checked;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("无法读取所选文件");checked=Backup.prepare(this,input);}if(isFinishing()||isDestroyed()){checked.close();return;}ui(()->{busy=false;plan=checked;if(checked.duplicate){status.setText("这个备份已经恢复过，不会重复添加卡片。");cancelDuplicate();return;}status.setText("校验通过，等待确认；现有数据尚未改变。");confirmation=new AlertDialog.Builder(this).setTitle("确认合并恢复？").setMessage(checked.summary()).setNegativeButton("取消",(d,w)->cancelImport()).setPositiveButton("合并恢复",(d,w)->confirmImport()).setOnCancelListener(d->cancelImport()).show();});}catch(Exception|OutOfMemoryError error){fail("备份校验未通过，没有恢复任何数据。",error);}});}}
    private void cancelDuplicate(){if(plan!=null){plan.close();plan=null;}}
    @Override public void onBackPressed(){if(busy){Toast.makeText(this,"正在处理备份，请稍等；原卡不会被覆盖。",Toast.LENGTH_SHORT).show();return;}cancelDuplicate();discardExport();super.onBackPressed();}
    @Override public void onDestroy(){if(confirmation!=null)confirmation.dismiss();if(!busy){cancelDuplicate();discardExport();}worker.shutdown();super.onDestroy();}
}
